"""Paste this entire file into a disconnected Langflow component's Code editor."""
from copy import deepcopy

from lfx.custom.custom_component.component import Component
from lfx.io import HandleInput, MessageTextInput, Output
from lfx.schema.message import Message


class MiraDispatcher(Component):
    """Forward the original request through exactly one allowed route."""

    display_name = "Mira Dispatcher"
    description = "Routes the original user message and stops unselected branches."
    icon = "git-branch"
    name = "MiraDispatcher"

    inputs = [
        MessageTextInput(
            name="route_label",
            display_name="Validated Route",
            info="Connect Mira Route Validator's Validated Route output.",
            required=True,
        ),
        HandleInput(
            name="user_message",
            display_name="Original User Message",
            info="Connect Chat Input directly to preserve request text and metadata.",
            input_types=["Message"],
            required=True,
        ),
    ]

    outputs = [
        Output(display_name="PLAN", name="plan", method="send_plan", group_outputs=True),
        Output(display_name="RISK", name="risk", method="send_risk", group_outputs=True),
        Output(display_name="STATUS", name="status_route", method="send_status", group_outputs=True),
        Output(display_name="MILESTONES", name="milestones", method="send_milestones", group_outputs=True),
        Output(display_name="COMMS", name="comms", method="send_comms", group_outputs=True),
        Output(display_name="CLARIFY", name="clarify", method="send_clarify", group_outputs=True),
        Output(display_name="UNSUPPORTED", name="unsupported", method="send_unsupported", group_outputs=True),
    ]

    def _deliver(self, requested_port: str) -> Message:
        """Validate each invocation and explicitly stop every inactive output.

        The empty Message is a typed return for an already stopped port; it is
        not the branch-control mechanism. No route is cached across requests.
        """
        ports = {
            "PLAN": "plan", "RISK": "risk", "STATUS": "status_route",
            "MILESTONES": "milestones", "COMMS": "comms",
            "CLARIFY": "clarify", "UNSUPPORTED": "unsupported",
        }
        raw = self.route_label
        label = raw.strip() if isinstance(raw, str) else ""
        if label not in ports:
            for port in ports.values():
                self.stop(port)
            self.status = "MIRA_INVALID_ROUTE"
            raise ValueError("MIRA_INVALID_ROUTE: Dispatch stopped; expected one allowed label.")

        message = self.user_message
        if not isinstance(message, Message) or not isinstance(message.text, str) or not message.text.strip():
            for port in ports.values():
                self.stop(port)
            self.status = "MIRA_MISSING_REQUEST"
            raise ValueError("MIRA_MISSING_REQUEST: A nonempty original user Message is required.")

        selected = ports[label]
        for port in ports.values():
            if port != selected:
                self.stop(port)

        self.status = f"Selected route: {label}"
        if requested_port != selected:
            return Message(text="")

        self.log(f"Mira dispatched route={label}")
        # Never forward a persisted input identity to Chat Output: it may
        # mutate and save that same record as an AI response.
        return Message(
            text=message.text,
            session_id=getattr(message, "session_id", "") or "",
            sender=getattr(message, "sender", "User") or "User",
            sender_name=getattr(message, "sender_name", "User") or "User",
            files=deepcopy(getattr(message, "files", None) or []),
        )

    def send_plan(self) -> Message:
        """Forward planning requests."""
        return self._deliver("plan")

    def send_risk(self) -> Message:
        """Forward risk requests."""
        return self._deliver("risk")

    def send_status(self) -> Message:
        """Forward task status requests."""
        return self._deliver("status_route")

    def send_milestones(self) -> Message:
        """Forward milestone requests."""
        return self._deliver("milestones")

    def send_comms(self) -> Message:
        """Forward requests for stakeholder drafts; never send email here."""
        return self._deliver("comms")

    def send_clarify(self) -> Message:
        """Forward incomplete requests to the clarification handler."""
        return self._deliver("clarify")

    def send_unsupported(self) -> Message:
        """Forward out-of-scope requests to the supported-capabilities handler."""
        return self._deliver("unsupported")

import csv
import io
import re
from collections import Counter
from datetime import date

from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.data import Data


class MiraTaskBoardValidator(Component):
    """Validate task-board CSV and calculate deterministic summaries."""

    display_name = "Mira Task Board Validator"
    description = "Validates task records and calculates status counts."
    icon = "table"
    name = "MiraTaskBoardValidator"

    inputs = [
        MessageTextInput(
            name="csv_text",
            display_name="Task Board CSV",
            info="Connect Read File's Raw Content output.",
            required=True,
        ),
    ]

    outputs = [
        Output(
            display_name="Validated Board",
            name="validated_board",
            method="build_board",
        ),
    ]

    def build_board(self) -> Data:
        """Return validated records and counts, or stop on invalid data."""
        columns = [
            "task_id",
            "task_name",
            "status",
            "assignee",
            "priority",
            "sprint",
            "due_date",
            "labels",
            "description",
        ]
        statuses = ("Done", "In Progress", "To Do", "Blocked")

        raw = self.csv_text
        if not isinstance(raw, str) or not raw.strip():
            raise ValueError(
                "MIRA_EMPTY_BOARD: Provide task-board CSV content."
            )

        # Remove an optional UTF-8 byte-order mark, not source values.
        reader = csv.DictReader(
            io.StringIO(raw.lstrip("\ufeff"), newline=""),
            strict=True,
        )

        tasks = []
        seen_ids = set()

        try:
            headers = reader.fieldnames
            if (
                headers is None
                or len(headers) != len(columns)
                or set(headers) != set(columns)
            ):
                raise ValueError(
                    "MIRA_INVALID_HEADERS: Expected exactly: "
                    + ", ".join(columns)
                )

            for row in reader:
                line = reader.line_num

                if None in row or any(
                    value is None for value in row.values()
                ):
                    raise ValueError(
                        f"MIRA_INVALID_ROW: Wrong column count "
                        f"near CSV line {line}."
                    )

                for field in (
                    "task_id", "task_name", "status", "sprint", "due_date"
                ):
                    if not row[field].strip():
                        raise ValueError(
                            f"MIRA_MISSING_FIELD: {field} is empty "
                            f"near CSV line {line}."
                        )

                task_id = row["task_id"]
                if not re.fullmatch(r"T[0-9]{3}", task_id):
                    raise ValueError(
                        f"MIRA_INVALID_TASK_ID: Expected T followed "
                        f"by three digits near CSV line {line}."
                    )

                if task_id in seen_ids:
                    raise ValueError(
                        f"MIRA_DUPLICATE_TASK: {task_id} occurs twice."
                    )

                if row["status"] not in statuses:
                    raise ValueError(
                        f"MIRA_INVALID_STATUS: {task_id} must use "
                        "Done, In Progress, To Do, or Blocked."
                    )

                if not re.fullmatch(
                    r"Sprint [1-9][0-9]*", row["sprint"]
                ):
                    raise ValueError(
                        f"MIRA_INVALID_SPRINT: {task_id} must use "
                        "a sprint label such as Sprint 3."
                    )

                due_date = row["due_date"]
                if not re.fullmatch(
                    r"[0-9]{4}-[0-9]{2}-[0-9]{2}", due_date
                ):
                    raise ValueError(
                        f"MIRA_INVALID_DATE: {task_id} requires "
                        "a YYYY-MM-DD due date."
                    )

                try:
                    date.fromisoformat(due_date)
                except ValueError as exc:
                    raise ValueError(
                        f"MIRA_INVALID_DATE: {task_id} has "
                        "an impossible calendar date."
                    ) from exc

                seen_ids.add(task_id)
                tasks.append(dict(row))

        except csv.Error as exc:
            raise ValueError(
                f"MIRA_INVALID_CSV: Malformed CSV near "
                f"line {reader.line_num}."
            ) from exc

        def summarize(records: list[dict[str, str]]) -> dict:
            """Count only the records supplied to this summary."""
            counts = Counter(record["status"] for record in records)
            return {
                "total_tasks": len(records),
                "counts": {
                    status: counts[status] for status in statuses
                },
                "task_ids": [
                    record["task_id"] for record in records
                ],
                "blocked_task_ids": [
                    record["task_id"]
                    for record in records
                    if record["status"] == "Blocked"
                ],
            }

        sprint_names = sorted(
            {task["sprint"] for task in tasks},
            key=lambda label: int(label.split()[1]),
        )
        by_sprint = {
            sprint: summarize(
                [task for task in tasks if task["sprint"] == sprint]
            )
            for sprint in sprint_names
        }

        result = {
            "schema_version": "1.0",
            "date_basis": "original_source_dates",
            "overall": summarize(tasks),
            "by_sprint": by_sprint,
            "tasks": tasks,
            "warnings": (
                ["The CSV contains headers but no task records."]
                if not tasks else []
            ),
        }

        self.status = f"Validated {len(tasks)} tasks"
        self.log(f"Task board validation succeeded: {len(tasks)} tasks")
        return Data(data=result)

"""Self-contained Langflow adapter; preserves the validated source board."""
import json
import re
from copy import deepcopy
from collections import Counter
from datetime import date, timedelta
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from lfx.custom.custom_component.component import Component
from lfx.io import HandleInput, MessageTextInput, Output
from lfx.schema.data import Data


class MiraScheduleAdapter(Component):
    """Derive task deadlines from an explicit, versioned configuration."""

    display_name = "Mira Schedule Adapter"
    description = "Adds effective deadlines without altering original task records."
    icon = "calendar"
    name = "MiraScheduleAdapter"
    inputs = [
        HandleInput(name="board_data", display_name="Validated Board",
                    input_types=["Data"], required=True),
        MessageTextInput(name="config_text", display_name="Configuration JSON",
                         required=True, info="Connect the configuration Read File's Raw Content."),
    ]
    outputs = [Output(display_name="Scheduled Board", name="scheduled_board",
                      method="build_schedule")]

    @staticmethod
    def _keys(value, expected: set[str], location: str) -> None:
        if not isinstance(value, dict) or set(value) != expected:
            raise ValueError(f"MIRA_INVALID_SCHEMA: Unexpected or missing fields in {location}.")

    @staticmethod
    def _date(value, location: str, nullable: bool = False):
        if value is None and nullable:
            return None
        if not isinstance(value, str) or not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", value):
            raise ValueError(f"MIRA_INVALID_DATE: {location} requires YYYY-MM-DD.")
        try:
            return date.fromisoformat(value)
        except ValueError as exc:
            raise ValueError(f"MIRA_INVALID_DATE: Invalid calendar date in {location}.") from exc

    @staticmethod
    def _unique(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("MIRA_INVALID_CONFIG: Duplicate JSON property.")
            result[key] = value
        return result

    def build_schedule(self) -> Data:
        """Validate configuration, copy source data, and calculate task flags."""
        if not isinstance(self.config_text, str) or not self.config_text.strip():
            raise ValueError("MIRA_MISSING_CONFIG: Configuration JSON is required.")
        try:
            cfg = json.loads(self.config_text.lstrip("\ufeff"), object_pairs_hook=self._unique)
        except json.JSONDecodeError as exc:
            raise ValueError("MIRA_INVALID_CONFIG: Malformed JSON.") from exc
        self._keys(cfg, {"config_version", "project_id", "timezone", "schedule"}, "config")
        if cfg["config_version"] != "1.0":
            raise ValueError("MIRA_INVALID_CONFIG: Unsupported configuration version.")
        if not isinstance(cfg["project_id"], str) or not re.fullmatch(r"[a-z0-9_]+", cfg["project_id"]):
            raise ValueError("MIRA_INVALID_CONFIG: Invalid project ID.")
        if not isinstance(cfg["timezone"], str):
            raise ValueError("MIRA_INVALID_CONFIG: Timezone must be a string.")
        try:
            ZoneInfo(cfg["timezone"])
        except (ZoneInfoNotFoundError, ValueError) as exc:
            raise ValueError("MIRA_INVALID_TIMEZONE: Unknown timezone or missing timezone database.") from exc
        s = cfg["schedule"]
        self._keys(s, {
            "mode", "actual_project_start_date", "original_reference_start_date",
            "original_reference_is_assumed", "demo_project_start_date", "reporting_date",
            "date_shift_policy", "timeline_week_policy", "milestone_deadline_policy",
            "preserve_source_files", "preserve_task_statuses", "preserve_sprint_assignments",
            "label_adjusted_reports_as_demo",
        }, "schedule")
        if s["mode"] not in ("original", "demo"):
            raise ValueError("MIRA_INVALID_CONFIG: Mode must be original or demo.")
        policies = {"date_shift_policy": "uniform_calendar_days",
                    "timeline_week_policy": "seven_day_periods_from_start",
                    "milestone_deadline_policy": "unknown"}
        for key, expected in policies.items():
            if s[key] != expected:
                raise ValueError(f"MIRA_INVALID_CONFIG: Unsupported {key}.")
        for key in ("preserve_source_files", "preserve_task_statuses",
                    "preserve_sprint_assignments", "label_adjusted_reports_as_demo"):
            if s[key] is not True:
                raise ValueError(f"MIRA_INVALID_CONFIG: {key} must be true.")
        if type(s["original_reference_is_assumed"]) is not bool:
            raise ValueError("MIRA_INVALID_CONFIG: Reference assumption must be boolean.")
        actual = self._date(s["actual_project_start_date"], "actual start", True)
        reference = self._date(s["original_reference_start_date"], "reference start", True)
        demo = self._date(s["demo_project_start_date"], "demo start", True)
        as_of = self._date(s["reporting_date"], "reporting date")
        if reference is not None and not s["original_reference_is_assumed"] and actual != reference:
            raise ValueError("MIRA_INVALID_CONFIG: Verified reference must equal known actual start.")
        shift = 0
        if s["mode"] == "demo":
            if reference is None or demo is None:
                raise ValueError("MIRA_INVALID_CONFIG: Demo mode requires both reference and demo starts.")
            shift = (demo - reference).days

        if not isinstance(self.board_data, Data):
            raise ValueError("MIRA_INVALID_BOARD: Connect a validated Data output.")
        source = self.board_data.data
        if not isinstance(source, dict) or source.get("schema_version") != "1.0" or source.get("date_basis") != "original_source_dates":
            raise ValueError("MIRA_INVALID_BOARD: Original-source board version 1.0 is required.")
        tasks = source.get("tasks")
        if not isinstance(tasks, list):
            raise ValueError("MIRA_INVALID_BOARD: Tasks must be a list.")
        statuses = ("Done", "In Progress", "To Do", "Blocked")
        required = {"task_id", "task_name", "status", "assignee", "priority", "sprint", "due_date", "labels", "description"}
        seen = set()
        scheduled = []
        for task in tasks:
            self._keys(task, required, "task row")
            if any(not isinstance(value, str) for value in task.values()):
                raise ValueError("MIRA_INVALID_BOARD: Task fields must be strings.")
            if not re.fullmatch(r"T[0-9]{3}", task["task_id"]) or task["task_id"] in seen:
                raise ValueError("MIRA_INVALID_BOARD: Invalid or duplicate task ID.")
            if task["status"] not in statuses or not task["task_name"].strip() or not re.fullmatch(r"Sprint [1-9][0-9]*", task["sprint"]):
                raise ValueError("MIRA_INVALID_BOARD: Invalid task name, status or sprint.")
            seen.add(task["task_id"])
            original = self._date(task["due_date"], task["task_id"])
            try:
                effective = original + timedelta(days=shift)
            except OverflowError as exc:
                raise ValueError("MIRA_INVALID_DATE: Shifted deadline is outside the supported range.") from exc
            item = deepcopy(task)
            item.update(effective_due_date=effective.isoformat(),
                        overdue_in_snapshot=task["status"] != "Done" and effective < as_of,
                        due_today_unfinished=task["status"] != "Done" and effective == as_of)
            scheduled.append(item)

        def summary(rows):
            counts = Counter(row["status"] for row in rows)
            return {"total_tasks": len(rows), "counts": {status: counts[status] for status in statuses},
                    "task_ids": [row["task_id"] for row in rows],
                    "blocked_task_ids": [row["task_id"] for row in rows if row["status"] == "Blocked"],
                    "overdue_task_ids": [row["task_id"] for row in rows if row["overdue_in_snapshot"]],
                    "due_today_task_ids": [row["task_id"] for row in rows if row["due_today_unfinished"]]}
        result = {"schema_version": "1.0", "date_basis": "demo_adjusted" if s["mode"] == "demo" else "original_source_dates",
                  "label": "DEMO SCHEDULE" if s["mode"] == "demo" else "ORIGINAL SOURCE SNAPSHOT",
                  "project_id": cfg["project_id"], "timezone": cfg["timezone"],
                  "reporting_date": as_of.isoformat(), "date_shift_days": shift,
                  "schedule_config": deepcopy(s), "source_board": deepcopy(source),
                  "overall": summary(scheduled),
                  "by_sprint": {name: summary([row for row in scheduled if row["sprint"] == name])
                                for name in sorted({row["sprint"] for row in scheduled}, key=lambda x: int(x.split()[1]))},
                  "tasks": scheduled,
                  "warnings": ["Task statuses are a source snapshot, not verified live progress.",
                               "No sprint calendar or task-to-milestone mapping is available.",
                               "This component adjusts task dates only; milestone deadlines remain unknown."]}
        self.status = f"{result['label']}: {shift:+d} days; {len(scheduled)} tasks"
        self.log(f"Schedule applied: mode={s['mode']}, shift_days={shift}, tasks={len(scheduled)}")
        return Data(data=result)

"""Validate timeline CSV and derive planned phase windows, not milestone deadlines."""
import csv
import hashlib
import io
import json
import re
from copy import deepcopy
from datetime import date, timedelta
from time import perf_counter
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.data import Data


class MiraTimelineAdapter(Component):
    """Build an auditable planned timeline from explicit configuration."""

    display_name = "Mira Timeline Adapter"
    description = "Validates timeline CSV and derives phase windows; milestone dates stay unknown."
    icon = "calendar"
    name = "MiraTimelineAdapter"
    inputs = [
        MessageTextInput(name="timeline_csv", display_name="Timeline CSV", required=True),
        MessageTextInput(name="config_text", display_name="Configuration JSON", required=True),
    ]
    outputs = [Output(display_name="Scheduled Timeline", name="scheduled_timeline",
                      method="build_timeline")]

    @staticmethod
    def _keys(value, expected: set[str], location: str) -> None:
        if not isinstance(value, dict) or set(value) != expected:
            raise ValueError(f"MIRA_INVALID_SCHEMA: Unexpected or missing fields in {location}.")

    @staticmethod
    def _date(value, location: str, nullable: bool = False):
        if value is None and nullable:
            return None
        if not isinstance(value, str) or not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", value):
            raise ValueError(f"MIRA_INVALID_DATE: {location} requires YYYY-MM-DD.")
        try:
            return date.fromisoformat(value)
        except ValueError as exc:
            raise ValueError(f"MIRA_INVALID_DATE: Invalid calendar date in {location}.") from exc

    @staticmethod
    def _unique(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("MIRA_INVALID_CONFIG: Duplicate JSON property.")
            result[key] = value
        return result

    def _read_config(self) -> tuple[dict, dict, date | None, date, str]:
        """Validate the same configuration contract used by the task adapter."""
        if not isinstance(self.config_text, str) or not self.config_text.strip():
            raise ValueError("MIRA_MISSING_CONFIG: Configuration JSON is required.")
        try:
            cfg = json.loads(self.config_text.lstrip("\ufeff"), object_pairs_hook=self._unique)
        except json.JSONDecodeError as exc:
            raise ValueError("MIRA_INVALID_CONFIG: Malformed JSON.") from exc
        self._keys(cfg, {"config_version", "project_id", "timezone", "schedule"}, "config")
        if cfg["config_version"] != "1.0":
            raise ValueError("MIRA_INVALID_CONFIG: Unsupported configuration version.")
        if not isinstance(cfg["project_id"], str) or not re.fullmatch(r"[a-z0-9_]+", cfg["project_id"]):
            raise ValueError("MIRA_INVALID_CONFIG: Invalid project ID.")
        if not isinstance(cfg["timezone"], str):
            raise ValueError("MIRA_INVALID_CONFIG: Timezone must be a string.")
        try:
            ZoneInfo(cfg["timezone"])
        except (ZoneInfoNotFoundError, ValueError) as exc:
            raise ValueError("MIRA_INVALID_TIMEZONE: Unknown timezone or missing timezone database.") from exc
        s = cfg["schedule"]
        self._keys(s, {
            "mode", "actual_project_start_date", "original_reference_start_date",
            "original_reference_is_assumed", "demo_project_start_date", "reporting_date",
            "date_shift_policy", "timeline_week_policy", "milestone_deadline_policy",
            "preserve_source_files", "preserve_task_statuses", "preserve_sprint_assignments",
            "label_adjusted_reports_as_demo",
        }, "schedule")
        if s["mode"] not in ("original", "demo"):
            raise ValueError("MIRA_INVALID_CONFIG: Mode must be original or demo.")
        policies = {"date_shift_policy": "uniform_calendar_days",
                    "timeline_week_policy": "seven_day_periods_from_start",
                    "milestone_deadline_policy": "unknown"}
        for key, expected in policies.items():
            if s[key] != expected:
                raise ValueError(f"MIRA_INVALID_CONFIG: Unsupported {key}.")
        for key in ("preserve_source_files", "preserve_task_statuses",
                    "preserve_sprint_assignments", "label_adjusted_reports_as_demo"):
            if s[key] is not True:
                raise ValueError(f"MIRA_INVALID_CONFIG: {key} must be true.")
        if type(s["original_reference_is_assumed"]) is not bool:
            raise ValueError("MIRA_INVALID_CONFIG: Reference assumption must be boolean.")
        actual = self._date(s["actual_project_start_date"], "actual start", True)
        reference = self._date(s["original_reference_start_date"], "reference start", True)
        demo = self._date(s["demo_project_start_date"], "demo start", True)
        as_of = self._date(s["reporting_date"], "reporting date")
        if reference is not None and not s["original_reference_is_assumed"] and actual != reference:
            raise ValueError("MIRA_INVALID_CONFIG: Verified reference must equal known actual start.")
        shift = 0
        if s["mode"] == "demo":
            if reference is None or demo is None:
                raise ValueError("MIRA_INVALID_CONFIG: Demo mode requires both reference and demo starts.")
            shift = (demo - reference).days

        anchor = demo if s["mode"] == "demo" else actual
        basis = "demo_phase_windows" if s["mode"] == "demo" else "actual_start_phase_windows" if actual else "relative_weeks_only"
        return cfg, s, anchor, as_of, basis

    def build_timeline(self) -> Data:
        """Preserve source rows and derive inclusive seven-day phase windows."""
        started = perf_counter()
        cfg, s, anchor, as_of, basis = self._read_config()
        raw = self.timeline_csv
        if not isinstance(raw, str) or not raw.strip():
            raise ValueError("MIRA_MISSING_TIMELINE: Connect the timeline Read File Raw Content.")
        if len(raw) > 1_000_000:
            raise ValueError("MIRA_INVALID_TIMELINE: Timeline exceeds the supported input size.")
        headers = ["phase", "phase_name", "start_week", "end_week", "key_activities", "milestones_deliverables"]
        try:
            reader = csv.DictReader(io.StringIO(raw.lstrip("\ufeff"), newline=""), strict=True)
            if reader.fieldnames != headers:
                raise ValueError("MIRA_INVALID_TIMELINE: Expected the six source headers in their original order.")
            rows = list(reader)
        except csv.Error as exc:
            raise ValueError("MIRA_INVALID_TIMELINE: Malformed CSV quoting or structure.") from exc
        if not rows:
            raise ValueError("MIRA_MISSING_TIMELINE: No phase records were supplied.")
        if len(rows) > 1000:
            raise ValueError("MIRA_INVALID_TIMELINE: More than 1000 phases are unsupported.")
        phases = []
        previous_end = 0
        for expected_id, row in enumerate(rows, start=1):
            if set(row) != set(headers) or any(not isinstance(v, str) or not v.strip() for v in row.values()):
                raise ValueError("MIRA_INVALID_TIMELINE: Missing, empty or extra CSV fields.")
            for field in ("phase", "start_week", "end_week"):
                if not re.fullmatch(r"[1-9][0-9]{0,3}", row[field]):
                    raise ValueError(f"MIRA_INVALID_TIMELINE: {field} requires a positive integer up to 9999.")
            phase_id, start_week, end_week = (int(row[k]) for k in ("phase", "start_week", "end_week"))
            if phase_id != expected_id:
                raise ValueError("MIRA_INVALID_TIMELINE: Phase IDs must be unique and sequential from 1 in source order.")
            if start_week > end_week or start_week != previous_end + 1:
                raise ValueError("MIRA_INVALID_TIMELINE: Expected contiguous, non-overlapping phases starting at week 1.")
            previous_end = end_week
            milestones = [item.strip() for item in row["milestones_deliverables"].split(";")]
            activities = [item.strip() for item in row["key_activities"].split(";")]
            if any(not item for item in milestones + activities):
                raise ValueError("MIRA_INVALID_TIMELINE: Empty activity or deliverable between separators.")
            start = end = None
            position = "unknown"
            if anchor is not None:
                try:
                    start = anchor + timedelta(days=(start_week - 1) * 7)
                    end = anchor + timedelta(days=end_week * 7 - 1)
                except OverflowError as exc:
                    raise ValueError("MIRA_INVALID_DATE: Derived phase window exceeds the supported calendar range.") from exc
                position = ("before_planned_window" if as_of < start else
                            "after_planned_window" if as_of > end else "within_planned_window")
            phases.append({
                "phase": phase_id, "phase_name": row["phase_name"],
                "start_week": start_week, "end_week": end_week,
                "planned_start_date": start.isoformat() if start else None,
                "planned_end_date": end.isoformat() if end else None,
                "reporting_date_position": position,
                "actual_progress": "unknown", "key_activities": activities,
                "milestones": [{"name": name, "deadline": None,
                                "completion_status": "unknown", "risk_status": "unknown"}
                               for name in milestones],
                "source_ref": {"file": "project_timeline.csv", "phase": row["phase"],
                               "record_number": expected_id},
                "source_row": deepcopy(row),
            })
        warnings = [
            "Phase windows are planned calendar intervals, not evidence of actual progress.",
            "Individual milestone deadlines, completion states and risk states are unknown.",
            "No task-to-milestone dependency mapping or sprint calendar is supplied.",
            "Weeks are consecutive seven-day periods from the chosen start, not ISO calendar weeks.",
        ]
        if s["mode"] == "demo":
            warnings.append("Demo phase windows are simulated; they are not confirmed project dates.")
        elif anchor is None:
            warnings.append("Actual project start is unknown. Supply it to derive original-mode calendar windows; the assumed reference is not used as an actual start.")
        elapsed = (perf_counter() - started) * 1000
        result = {
            "schema_version": "1.0", "project_id": cfg["project_id"],
            "timezone": cfg["timezone"], "date_basis": basis,
            "label": "DEMO SCHEDULE" if s["mode"] == "demo" else "ORIGINAL TIMELINE",
            "reporting_date": as_of.isoformat(),
            "calendar_anchor_date": anchor.isoformat() if anchor else None,
            "calendar_dates_available": anchor is not None,
            "schedule_config": deepcopy(s),
            "source": {"file": "project_timeline.csv", "sha256_loaded_text": hashlib.sha256(raw.encode("utf-8")).hexdigest()},
            "total_phases": len(phases), "total_weeks": previous_end,
            "phases_containing_reporting_date": [p["phase"] for p in phases if p["reporting_date_position"] == "within_planned_window"],
            "phases": phases, "warnings": warnings,
        }
        self.status = f"{result['label']}: {len(phases)} phases; {previous_end} weeks"
        self.log(f"mira_timeline_adapter phases={len(phases)} duration_ms={elapsed:.1f} model_calls=0")
        return Data(data=result)
